create or replace function public.stamp_audit_actor_name() returns trigger language plpgsql security definer set search_path=public as $$ declare v_name text;begin select full_name into v_name from public.profiles where id=coalesce(new.actor_id,auth.uid());new.details:=jsonb_set(coalesce(new.details,'{}'::jsonb),'{actor_name}',to_jsonb(coalesce(v_name,'Unknown / system')),true);return new;end $$;drop trigger if exists audit_logs_stamp_actor on public.audit_logs;create trigger audit_logs_stamp_actor before insert on public.audit_logs for each row execute function public.stamp_audit_actor_name();revoke all on function public.stamp_audit_actor_name() from public,anon,authenticated;
do $$ begin if not exists(select 1 from pg_constraint where conname='project_control_contract_date_order') then alter table public.project_control add constraint project_control_contract_date_order check(contract_start_date is null or contract_end_date is null or contract_start_date<=contract_end_date);end if;if not exists(select 1 from pg_constraint where conname='project_control_actual_date_order') then alter table public.project_control add constraint project_control_actual_date_order check(actual_start_date is null or actual_end_date is null or actual_start_date<=actual_end_date);end if;end $$;